with i as (select source_run_id,order_id,sum(price) merchandise_amount,sum(freight_value) freight_amount,count(*) item_count from {{ ref('order_items') }} group by 1,2), p as (select source_run_id,order_id,sum(payment_value) payment_amount,count(*) payment_count from {{ ref('order_payments') }} group by 1,2) select o.*,coalesce(i.merchandise_amount,0) merchandise_amount,coalesce(i.freight_amount,0) freight_amount,coalesce(i.merchandise_amount+i.freight_amount,0) gross_amount,coalesce(p.payment_amount,0) payment_amount,coalesce(p.payment_amount,0)-coalesce(i.merchandise_amount+i.freight_amount,0) payment_delta,coalesce(i.item_count,0) item_count,coalesce(p.payment_count,0) payment_count from {{ ref('orders') }} o left join i using(source_run_id,order_id) left join p using(source_run_id,order_id)
